import { step } from "@cori-do/sdk";
import type { Ctx } from "../.cori/context";
import { z } from "zod";
import { Plan } from "../types";

// `store` step on a typed tool generated by the Store from the role in the exchanged JWT.
// Effect = Read because `support_agent` only has `readable` on customers.
export default step.store({
  name: "lookup_customer",
  description: "Look up the customer's plan",
  connector: "tickets",
  tool: "getCustomer",
  input: (ctx: Ctx<"lookup_customer">) => ({ id: ctx.steps.load_ticket.ticket.customer_id }),
  output: z.object({ plan: Plan, arr_eur: z.number() }),
});
